#include "../src/holiday_names.hpp"
#include <cassert>
#include <iostream>
using namespace day;
int main(){std::ifstream f("assets/holiday-names-ru.json");f>>holidayNames();assert(holidayNames()["english"].size()>=700);Holiday german{"2026-10-03","Tag der Deutschen Einheit","DE","German Unity Day"};assert(localizedHolidayTitle(german,0)=="День германского единства");assert(localizedHolidayTitle(german,1)=="German Unity Day");german.english.clear();assert(localizedHolidayTitle(german,0)=="День германского единства");Holiday apostrophe{"2026-03-08","Жіночий день","UA","International Women’s Day"};assert(localizedHolidayTitle(apostrophe,0)=="Международный женский день");Holiday christmas{"2026-12-25","Natal","BR","Christmas Day"};assert(localizedHolidayTitle(christmas,0)=="Рождество");Holiday unknown{"2026-10-07","Новый местный праздник","XX","New future observance"};assert(localizedHolidayTitle(unknown,0)==unknown.name&&localizedHolidayTitle(unknown,1)==unknown.english);Holiday international{"2026-10-24","День ООН","INT","United Nations Day"};assert(localizedHolidayTitle(international,0)=="День ООН");int aliases=0;for(auto country=holidayNames()["local"].begin();country!=holidayNames()["local"].end();++country)for(auto it=country->begin();it!=country->end();++it){Holiday h{"2026-01-01",it.key(),country.key(),""};if(localizedHolidayTitle(h,0)!=it->get<std::string>()){std::cerr<<country.key()<<" / "<<it.key()<<": "<<localizedHolidayTitle(h,0)<<" != "<<it->get<std::string>()<<"\n";return 1;}++aliases;}std::cout<<"Offline Russian holidays, English, curly apostrophe, legacy caches, country aliases ("<<aliases<<") and unknown-name fallback: PASS\n";}
